// EGXANO brand components — the Aperture Index mark and lockups.
// Source of truth for geometry: public/*.svg (generated by
// scripts/generate-brand-assets.mjs). These inline components exist so the
// header/footer/sidebars can color the mark with theme tokens and keep it
// crisp at any size without extra network requests.

const STROKE = 3.375; // 54/16 on the 160 grid

export function BrandMark({
  size = 28,
  ring = "currentColor",
  signal = "var(--brand-accent, #A3E635)",
  className,
}: {
  size?: number;
  ring?: string;
  signal?: string;
  className?: string;
}) {
  // Ring: center (80,82.5) r=41.25, aperture -12°→-78°; bar: 45° signal.
  const x1 = 80 + 41.25 * Math.cos((-12 * Math.PI) / 180);
  const y1 = 82.5 + 41.25 * Math.sin((-12 * Math.PI) / 180);
  const x2 = 80 + 41.25 * Math.cos((282 * Math.PI) / 180);
  const y2 = 82.5 + 41.25 * Math.sin((282 * Math.PI) / 180);
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 160 160"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d={`M ${x1} ${y1} A 41.25 41.25 0 1 1 ${x2} ${y2}`}
        stroke={ring}
        strokeWidth={STROKE}
        strokeLinecap="round"
      />
      <path d="M 63.75 98.75 L 130 32.5" stroke={signal} strokeWidth={STROKE} strokeLinecap="round" />
    </svg>
  );
}

/**
 * Header lockup: mark + EGXANO wordmark (Latin wordmark per brand rules —
 * no Arabic text inside the logo symbol). On light surfaces the ink is the
 * foreground token; the signal uses the accessible deep lime on light and
 * acid lime on dark via the `brand-accent` CSS variable.
 */
export function BrandLockup({ compact = false }: { compact?: boolean }) {
  return (
    <span className="flex items-center gap-2 text-foreground">
      <BrandMark size={compact ? 24 : 28} className="shrink-0" />
      <span className="flex flex-col items-start leading-none">
        <span className="text-sm font-extrabold tracking-[0.08em]">EGXANO</span>
        {!compact && (
          <span className="mt-0.5 text-[9px] font-medium tracking-wide text-muted-foreground">
            EGX research
          </span>
        )}
      </span>
    </span>
  );
}
